"use client";
import {ArtemisScope} from "./artemis-scope";
import type { ArtemisPricingContent } from "./components/pricing/content";
import View0 from "./components/pricing/variants/01-ai";
import View1 from "./components/pricing/variants/02-shared-benefits";
import View2 from "./components/pricing/variants/05-aurora-flow";
import View3 from "./components/pricing/variants/06-visual-plans";
import View4 from "./components/pricing/variants/07-command-deck";
import View5 from "./components/pricing/variants/08-ledger";
import View6 from "./components/pricing/variants/11-plans-grid";
const views={"ai":View0,"shared-benefits":View1,"aurora-flow":View2,"visual-plans":View3,"command-deck":View4,"ledger":View5,"plans-grid":View6};
export type { ArtemisPricingBenefits, ArtemisPricingBilling, ArtemisPricingCalculator, ArtemisPricingContent, ArtemisPricingImage, ArtemisPricingLink, ArtemisPricingPlan, ArtemisPricingTier } from "./components/pricing/content";
export interface ArtemisPricingProps {className?:string;variant?:"ai"|"shared-benefits"|"aurora-flow"|"visual-plans"|"command-deck"|"ledger"|"plans-grid";/** The words on the pricing section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisPricingContent>;}
export function ArtemisPricing({className,variant="ai",content}:ArtemisPricingProps){const View=views[variant];return <ArtemisScope className={`art:[&>*]:mx-auto ${className??""}`}><View content={content}/></ArtemisScope>;}
